-- Semantic Kernel phase-1 shadow schema. Legacy tables remain readable while
-- each domain is migrated behind a feature flag and replay gate.
CREATE TABLE IF NOT EXISTS agent_threads (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, owner_user_id TEXT, status TEXT NOT NULL, schema_version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agent_turns (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, thread_id TEXT NOT NULL, status TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, terminal_outcome TEXT);
CREATE TABLE IF NOT EXISTS agent_event_ledger (event_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, thread_id TEXT NOT NULL, turn_id TEXT, sequence INTEGER NOT NULL, batch_id TEXT NOT NULL, schema_version INTEGER NOT NULL, event_type TEXT NOT NULL, payload_json TEXT NOT NULL, payload_hash TEXT NOT NULL, idempotency_key TEXT, durable INTEGER NOT NULL DEFAULT 0, occurred_at TEXT NOT NULL, UNIQUE(thread_id, sequence), UNIQUE(thread_id, idempotency_key));
CREATE TABLE IF NOT EXISTS agent_projection_cursors (tenant_id TEXT NOT NULL, projection_name TEXT NOT NULL, thread_id TEXT NOT NULL, last_sequence INTEGER NOT NULL DEFAULT 0, revision INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL, PRIMARY KEY(tenant_id, projection_name, thread_id));
CREATE TABLE IF NOT EXISTS ledger_repair_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, thread_id TEXT NOT NULL, from_sequence INTEGER, to_sequence INTEGER, repair_kind TEXT NOT NULL, diagnostic_json TEXT NOT NULL, operator_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tool_invocations (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, thread_id TEXT NOT NULL, turn_id TEXT, tool_name TEXT NOT NULL, lifecycle_state TEXT NOT NULL, idempotency_key TEXT NOT NULL, capability_token_id TEXT, artifact_id TEXT, outcome TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approval_requests (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, thread_id TEXT NOT NULL, tool_name TEXT NOT NULL, scope_hash TEXT NOT NULL, status TEXT NOT NULL, expires_at TEXT, max_uses INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS capability_tokens (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, user_id TEXT NOT NULL, session_id TEXT, tool_name TEXT NOT NULL, resource_scope TEXT NOT NULL, action_scope TEXT NOT NULL, executor_scope TEXT, child_scope TEXT, expires_at TEXT NOT NULL, remaining_uses INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS child_thread_edges (parent_thread_id TEXT NOT NULL, child_thread_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, spawn_item_id TEXT NOT NULL, settlement TEXT, detached INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS execution_checkpoints (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, thread_id TEXT NOT NULL, sequence INTEGER NOT NULL, state_hash TEXT NOT NULL, checkpoint_json TEXT NOT NULL, durable INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS artifact_objects (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, owner_scope TEXT NOT NULL, content_hash TEXT NOT NULL, media_type TEXT NOT NULL, byte_size INTEGER NOT NULL, locator TEXT NOT NULL, retention_policy TEXT NOT NULL, expires_at TEXT, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS artifact_projections (artifact_id TEXT NOT NULL, projection_kind TEXT NOT NULL, policy_version TEXT NOT NULL, projection_hash TEXT NOT NULL, payload_json TEXT NOT NULL, omitted_bytes INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, PRIMARY KEY(artifact_id, projection_kind));
CREATE TABLE IF NOT EXISTS resource_budget_accounts (tenant_id TEXT NOT NULL, owner_scope TEXT NOT NULL, dimension TEXT NOT NULL, available INTEGER NOT NULL, reserved INTEGER NOT NULL DEFAULT 0, committed INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(tenant_id, owner_scope, dimension));
CREATE TABLE IF NOT EXISTS resource_budget_entries (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, owner_scope TEXT NOT NULL, reservation_id TEXT NOT NULL, dimension TEXT NOT NULL, amount INTEGER NOT NULL, state TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS semantic_assertions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, scope_json TEXT NOT NULL, subject_json TEXT NOT NULL, predicate TEXT NOT NULL, value_json TEXT NOT NULL, status TEXT NOT NULL, confidence REAL NOT NULL, observed_at TEXT NOT NULL, valid_time_json TEXT, sensitivity TEXT NOT NULL, retention_policy TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS semantic_assertion_edges (assertion_id TEXT NOT NULL, related_assertion_id TEXT NOT NULL, relation TEXT NOT NULL, PRIMARY KEY(assertion_id, related_assertion_id, relation));
CREATE TABLE IF NOT EXISTS semantic_snapshots (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, scope TEXT NOT NULL, version INTEGER NOT NULL, snapshot_hash TEXT NOT NULL, snapshot_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence_ledger (evidence_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, source_type TEXT NOT NULL, source_locator TEXT NOT NULL, content_hash TEXT NOT NULL, event_seq INTEGER, range_json TEXT, authority TEXT NOT NULL, collected_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS decision_records (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, scope TEXT NOT NULL, question TEXT NOT NULL, decision TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL, record_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS compaction_checkpoints (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, thread_id TEXT NOT NULL, source_event_seqs_json TEXT NOT NULL, checkpoint_json TEXT NOT NULL, source_hash TEXT NOT NULL, extractor_version TEXT NOT NULL, prompt_version TEXT NOT NULL, durable INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS context_packet_manifests (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, thread_id TEXT NOT NULL, turn_id TEXT, snapshot_version INTEGER, manifest_hash TEXT NOT NULL, manifest_json TEXT NOT NULL, model_version TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requirement_states (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, version INTEGER NOT NULL, readiness TEXT NOT NULL, state_json TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS requirement_state_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, requirement_id TEXT NOT NULL, version INTEGER NOT NULL, source_event_ids_json TEXT NOT NULL, delta_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS metric_contracts (id TEXT NOT NULL, tenant_id TEXT NOT NULL, version INTEGER NOT NULL, status TEXT NOT NULL, contract_json TEXT NOT NULL, valid_from TEXT NOT NULL, valid_until TEXT, PRIMARY KEY(tenant_id, id, version));
CREATE TABLE IF NOT EXISTS join_contracts (id TEXT NOT NULL, tenant_id TEXT NOT NULL, version INTEGER NOT NULL, status TEXT NOT NULL, contract_json TEXT NOT NULL, PRIMARY KEY(tenant_id, id, version));
CREATE TABLE IF NOT EXISTS analytic_intent_ir (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, thread_id TEXT, turn_id TEXT, ir_json TEXT NOT NULL, ir_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS semantic_verifications (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, analytic_intent_id TEXT NOT NULL, verification_json TEXT NOT NULL, release_decision TEXT NOT NULL, calibrated_score REAL NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS feedback_learning_events (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, scope TEXT NOT NULL, correction_json TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0, regression_case_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS nl2sql_confidence_observations (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, datasource_id TEXT NOT NULL, analytic_intent_id TEXT NOT NULL, predicted_score REAL NOT NULL, actual_correct INTEGER, feedback_id INTEGER, created_at TEXT NOT NULL, labeled_at TEXT);
CREATE TABLE IF NOT EXISTS eval_runs (id TEXT PRIMARY KEY, tenant_id TEXT, suite_id TEXT NOT NULL, seed INTEGER NOT NULL, config_hash TEXT NOT NULL, status TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT);
CREATE TABLE IF NOT EXISTS eval_case_results (run_id TEXT NOT NULL, case_id TEXT NOT NULL, scenario TEXT NOT NULL, result_json TEXT NOT NULL, PRIMARY KEY(run_id, case_id));
CREATE INDEX IF NOT EXISTS idx_agent_event_ledger_thread_seq ON agent_event_ledger(tenant_id, thread_id, sequence);
CREATE INDEX IF NOT EXISTS idx_semantic_assertions_scope ON semantic_assertions(tenant_id, scope_json, status);
CREATE INDEX IF NOT EXISTS idx_evidence_ledger_tenant_event ON evidence_ledger(tenant_id, event_seq);
CREATE INDEX IF NOT EXISTS idx_artifact_objects_retention ON artifact_objects(tenant_id, expires_at, deleted_at);
CREATE INDEX IF NOT EXISTS idx_requirement_events_version ON requirement_state_events(tenant_id, requirement_id, version);
CREATE INDEX IF NOT EXISTS idx_nl2sql_confidence_scope ON nl2sql_confidence_observations(tenant_id, datasource_id, actual_correct, created_at);
